29	
30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	import org.springframework.http.HttpHeaders;
33	import org.springframework.http.HttpStatus;
34	import org.springframework.http.ResponseEntity;
35	import org.springframework.samples.petclinic.mapper.OwnerMapper;
36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.advice.CityCapacityException;
42	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
44	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
45	import org.springframework.samples.petclinic.rest.advice.InvalidRequestException;
46	import org.springframework.samples.petclinic.rest.api.OwnersApi;
47	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
48	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.PetDto;
50	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
53	import org.springframework.samples.petclinic.service.ClinicService;
54	import org.springframework.security.access.prepost.PreAuthorize;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	import org.springframework.util.StringUtils;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
74	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
75	     * and a dotted domain (e.g. {@code not-an-email}).
76	     */
77	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
78	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
79	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
80	
81	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
82	    private static final String DEFAULT_COUNTRY_CODE = "61";
83	
84	    /** Maximum number of owners a single city may contain; a create is rejected once it is reached. */
85	    private static final int MAX_OWNERS_PER_CITY = 50;
86	
87	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
88	    private static final int MAX_OWNERS_PER_DAY = 100;
89	
90	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
91	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
92	
93	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
94	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
95	
96	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
97	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
98	        "ST", "STREET",
99	        "RD", "ROAD",
100	        "AVE", "AVENUE");
101	
102	    /** Dedicated audit logger; a create side-effect is recorded here on success. */
103	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
104	
105	    private final ClinicService clinicService;
106	
107	    private final OwnerMapper ownerMapper;
108	
109	    private final PetMapper petMapper;
110	
111	    private final VisitMapper visitMapper;
112	
113	    public OwnerRestControllerV1(ClinicService clinicService,
114	                                 OwnerMapper ownerMapper,
115	                                 PetMapper petMapper,
116	                                 VisitMapper visitMapper) {
117	        this.clinicService = clinicService;
118	        this.ownerMapper = ownerMapper;
119	        this.petMapper = petMapper;
120	        this.visitMapper = visitMapper;
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
126	        Collection<Owner> owners;
127	        if (lastName != null) {
128	            owners = this.clinicService.findOwnerByLastName(lastName);
129	        } else {
130	            owners = this.clinicService.findAllOwners();
131	        }
132	        if (owners.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
151	        List<String> missingFields = new ArrayList<>();
152	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
153	            missingFields.add("firstName");
154	        }
155	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
156	            missingFields.add("lastName");
157	        }
158	        // Normalize the address up front; the required-field check rejects it when it is blank
159	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
160	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
161	        if (!StringUtils.hasText(normalizedAddress)) {
162	            missingFields.add("address");
163	        }
164	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
165	            missingFields.add("city");
166	        }
167	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
168	            missingFields.add("telephone");
169	        }
170	        if (!missingFields.isEmpty()) {
171	            throw new InvalidRequestException(missingFields);
172	        }
173	        HttpHeaders headers = new HttpHeaders();
174	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
175	        // Store (and later return) the normalized address computed above.
176	        owner.setAddress(normalizedAddress);
177	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
178	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
179	        owner.setTelephone(normalizedTelephone);
180	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
181	        owner.setEmail(normalizeEmail(owner.getEmail()));
182	        // Default the (optional) registration date to the server's current date when none was supplied.
183	        if (owner.getRegistrationDate() == null) {
184	            owner.setRegistrationDate(LocalDate.now());
185	        }
186	        // The effective registration date must fall on a business day: when it lands on a Saturday or
187	        // Sunday (whether supplied or defaulted above), roll it forward to the next Monday. Every value
188	        // derived from the registration date below (daily create-limit, membership number) uses this
189	        // adjusted date.
190	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
191	        // Reject the request once the maximum number of owners for the owner's registration day has
192	        // been reached (100 or more owners already created on that date).
193	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
194	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
195	        }
196	        // Reject the request when the owner's city has already reached its owner capacity.
197	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
198	            throw new CityCapacityException(owner.getCity());
199	        }
200	        // Reject the request if the E.164 telephone is already used by another owner.
201	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
202	            throw new DuplicateTelephoneException(normalizedTelephone);
203	        }
204	        // Reject the request if another owner already shares the same last name and address
205	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
206	        // by setting 'sharesHousehold' true. When they do opt in and an existing household is
207	        // matched, assign a stable shared 'householdId' to the new owner and backfill it onto
208	        // every existing member that does not yet carry it.
209	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
210	        if (!householdMembers.isEmpty()) {
211	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
212	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
213	            }
214	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
215	            owner.setHouseholdId(householdId);
216	            for (Owner member : householdMembers) {
217	                if (!householdId.equals(member.getHouseholdId())) {
218	                    member.setHouseholdId(householdId);
219	                    this.clinicService.saveOwner(member);
220	                }
221	            }
222	        }
223	        // Record how many existing owners already share this first name and last name
224	        // (compared case-insensitively) before this owner is created.
225	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
226	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' before persisting.
227	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
228	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
229	        // digits of the registration date year (e.g. 'SYD-SMI-0007-M26').
230	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
231	        this.clinicService.saveOwner(owner);
232	        // Emit an audit line carrying the new owner's id, customer code and registration date.
233	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
234	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
235	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
236	        headers.setLocation(UriComponentsBuilder.newInstance()
237	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
238	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
244	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
245	        if (currentOwner == null) {
246	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	        }
248	        currentOwner.setAddress(ownerFieldsDto.getAddress());
249	        currentOwner.setCity(ownerFieldsDto.getCity());
250	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
251	        currentOwner.setLastName(ownerFieldsDto.getLastName());
252	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
253	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
254	        this.clinicService.saveOwner(currentOwner);
255	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
256	    }
257	
258	    /**
259	     * Generate a customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the
260	     * upper-cased first three letters of {@code city}, {@code LAST3} is the upper-cased first three
261	     * letters of {@code lastName} and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to
262	     * one more than the current number of owners already in that city (e.g. {@code SYD-SMI-0007}).
263	     *
264	     * @param city     the owner's city
265	     * @param lastName the owner's last name
266	     * @return the generated customer code
267	     */
268	    private String generateCustomerCode(String city, String lastName) {
269	        String cityPrefix = city.length() >= 3 ? city.substring(0, 3) : city;
270	        String lastPrefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
271	        String normalizedCity = normalizeForComparison(city);
272	        int sequence = (int) this.clinicService.findAllOwners().stream()
273	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
274	            .count() + 1;
275	        return String.format("%s-%s-%04d", cityPrefix.toUpperCase(Locale.ROOT),
276	            lastPrefix.toUpperCase(Locale.ROOT), sequence);
277	    }
278	
279	    /**
280	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
281	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
282	     * that is stored, returned and used for every value derived from it.
283	     *
284	     * @param date the effective registration date (supplied or defaulted)
285	     * @return the same date when it is a weekday, otherwise the next Monday
286	     */
287	    private LocalDate rollToBusinessDay(LocalDate date) {
288	        DayOfWeek dayOfWeek = date.getDayOfWeek();
289	        if (dayOfWeek == DayOfWeek.SATURDAY) {
290	            return date.plusDays(2);
291	        }
292	        if (dayOfWeek == DayOfWeek.SUNDAY) {
293	            return date.plusDays(1);
294	        }
295	        return date;
296	    }
297	
298	    /**
299	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
300	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
301	     *
302	     * @param customerCode     the owner's already-assigned customer code
303	     * @param registrationDate the owner's registration date
304	     * @return the generated membership number
305	     */
306	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
307	        String yy = String.format("%02d", registrationDate.getYear() % 100);
308	        return String.format("%s-M%s", customerCode, yy);
309	    }
310	
311	    /**
312	     * Count the existing owners that share the given first name and last name, comparing each
313	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
314	     * yet persisted, so it is not included in the count.
315	     *
316	     * @param firstName the incoming owner's first name
317	     * @param lastName  the incoming owner's last name
318	     * @return the number of existing namesakes
319	     */
320	    private int countNamesakes(String firstName, String lastName) {
321	        String normalizedFirstName = normalizeForComparison(firstName);
322	        String normalizedLastName = normalizeForComparison(lastName);
323	        return (int) this.clinicService.findAllOwners().stream()
324	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
325	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
326	            .count();
327	    }
328	
329	    /**
330	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
331	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
332	     *
333	     * @param city the incoming owner's city
334	     * @return the number of existing owners already in that city
335	     */
336	    private int countOwnersInCity(String city) {
337	        String normalizedCity = normalizeForComparison(city);
338	        return (int) this.clinicService.findAllOwners().stream()
339	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
340	            .count();
341	    }
342	
343	    /**
344	     * Count the existing owners whose registration date equals the given date. The incoming owner is
345	     * not yet persisted, so it is not included in the count.
346	     *
347	     * @param registrationDate the incoming owner's registration date
348	     * @return the number of existing owners already registered on that date
349	     */
350	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
351	        return (int) this.clinicService.findAllOwners().stream()
352	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
353	            .count();
354	    }
355	
356	    /**
357	     * Find the existing owners that live in the same household as the given values, i.e. those that
358	     * share both the last name and the address when each is compared case-insensitively with
359	     * collapsed whitespace.
360	     *
361	     * @param lastName the incoming owner's last name
362	     * @param address  the incoming owner's address
363	     * @return the matching existing owners (possibly empty)
364	     */
365	    private List<Owner> findHouseholdMembers(String lastName, String address) {
366	        String normalizedLastName = normalizeForComparison(lastName);
367	        String normalizedAddress = normalizeForComparison(address);
368	        return this.clinicService.findAllOwners().stream()
369	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
370	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
371	            .toList();
372	    }
373	
374	    /**
375	     * Generate a stable shared household identifier for the given last name and address. The value is
376	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
377	     * and address, so every owner joining the same household resolves to the same identifier. It is the
378	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
379	     *
380	     * @param lastName the household's last name
381	     * @param address  the household's address
382	     * @return the stable household identifier
383	     */
384	    private String generateHouseholdId(String lastName, String address) {
385	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
386	        try {
387	            byte[] digest = MessageDigest.getInstance("SHA-256")
388	                .digest(key.getBytes(StandardCharsets.UTF_8));
389	            StringBuilder sb = new StringBuilder(digest.length * 2);
390	            for (byte b : digest) {
391	                sb.append(String.format("%02x", b));
392	            }
393	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
394	        } catch (java.security.NoSuchAlgorithmException e) {
395	            throw new IllegalStateException("SHA-256 not available", e);
396	        }
397	    }
398	
399	    /**
400	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
401	     * single space, upper-case the result and expand common street-type abbreviations token by token
402	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
403	     * to the empty string. The result is the canonical form that is stored, returned and used for every
404	     * address comparison (household duplicate detection and the shared household id).
405	     *
406	     * @param address the raw address, may be {@code null}
407	     * @return the normalized address
408	     */
409	    private String normalizeAddress(String address) {
410	        if (address == null) {
411	            return "";
412	        }
413	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
414	        if (collapsed.isEmpty()) {
415	            return "";
416	        }
417	        String[] tokens = collapsed.split(" ");
418	        StringBuilder sb = new StringBuilder(collapsed.length());
419	        for (int i = 0; i < tokens.length; i++) {
420	            if (i > 0) {
421	                sb.append(' ');
422	            }
423	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
424	        }
425	        return sb.toString();
426	    }
427	
428	    /**
429	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
430	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
431	     *
432	     * @param value the raw value, may be {@code null}
433	     * @return the normalized value
434	     */
435	    private String normalizeForComparison(String value) {
436	        if (value == null) {
437	            return "";
438	        }
439	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
440	    }
441	
442	    /**
443	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
444	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
445	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
446	     * is returned lower-cased.
447	     *
448	     * @param email the raw email from the request payload, may be {@code null}
449	     * @return the lower-cased email, or {@code null} when none was provided
450	     */
451	    private String normalizeEmail(String email) {
452	        if (!StringUtils.hasText(email)) {
453	            return null;
454	        }
455	        if (!EMAIL_PATTERN.matcher(email).matches()) {
456	            throw new InvalidRequestException(List.of("email"));
457	        }
458	        return email.toLowerCase(Locale.ROOT);
459	    }
460	
461	    /**
462	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
463	     * already carries a leading '+' keeps its country code; otherwise the default country code
464	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
465	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
466	     * is thrown (mapped to 400 Bad Request).
467	     *
468	     * @param telephone the raw telephone from the request payload
469	     * @return the E.164 string (e.g. {@code +61412345678})
470	     */
471	    private String normalizeTelephone(String telephone) {
472	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
473	        String candidate;
474	        if (cleaned.startsWith("+")) {
475	            candidate = cleaned;
476	        } else {
477	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
478	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
479	        }
480	        if (!E164_PATTERN.matcher(candidate).matches()) {
481	            throw new InvalidRequestException(List.of("telephone"));
482	        }
483	        return candidate;
484	    }
485	
486	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
487	    @Transactional
488	    @Override
489	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
490	        Owner owner = this.clinicService.findOwnerById(ownerId);
491	        if (owner == null) {
492	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
493	        }
494	        this.clinicService.deleteOwner(owner);
495	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
496	    }
497	
498	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
499	    @Override
500	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
501	        Owner owner = this.clinicService.findOwnerById(ownerId);
502	        if (owner == null) {
503	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
504	        }
505	        HttpHeaders headers = new HttpHeaders();
506	        Pet pet = petMapper.toPet(petFieldsDto);
507	        owner.setId(ownerId);
508	        pet.setOwner(owner);
509	        pet.getType().setName(null);
510	        this.clinicService.savePet(pet);
511	        PetDto petDto = petMapper.toPetDto(pet);
512	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
513	            .buildAndExpand(pet.getId()).toUri());
514	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
515	    }
516	
517	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
518	    @Override
519	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
520	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
521	        if (currentOwner != null) {
522	            Pet currentPet = this.clinicService.findPetById(petId);
523	            if (currentPet != null) {
524	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
525	                currentPet.setName(petFieldsDto.getName());
526	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
527	                this.clinicService.savePet(currentPet);
528	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
529	            }
530	        }
531	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
532	    }
533	
534	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
535	    @Override
536	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
537	        HttpHeaders headers = new HttpHeaders();
538	        Visit visit = visitMapper.toVisit(visitFieldsDto);
539	        Pet pet = new Pet();
540	        pet.setId(petId);
541	        visit.setPet(pet);
542	        this.clinicService.saveVisit(visit);
543	        VisitDto visitDto = visitMapper.toVisitDto(visit);
544	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
545	            .buildAndExpand(visit.getId()).toUri());
546	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
547	    }
548	
549	
550	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
551	    @Override
552	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
553	        Owner owner = this.clinicService.findOwnerById(ownerId);
554	        if (owner != null) {
555	            Pet pet = owner.getPet(petId);
556	            if (pet != null) {
557	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
558	            }
559	        }
560	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
561	    }
562	}
